package engtelecom.poo;

import engtelecom.poo.modelos.ChevroletS10;
import engtelecom.poo.modelos.FerrariPortoFino;
import engtelecom.poo.modelos.WaterCarPanther;
import engtelecom.poo.veiculos.Veiculo;

import java.util.ArrayList;

public class App {
    public static void main(String[] args) {

        ArrayList<Veiculo> carros = new ArrayList<>();

        carros.add(new ChevroletS10());
        carros.add(new FerrariPortoFino());
        carros.add(new WaterCarPanther());

        for (int i = 0; i < 350; i++) {

            carros.forEach(v -> v.acelerar());

            carros.forEach(v -> {

                        IO.print(v.getClass().getSimpleName() + " Acelerou para: ");
                        IO.println(v.getVelocidadeAtual());


                    }
            );
        }
        carros.forEach(c -> {

            // Ferrari
            if (c instanceof FerrariPortoFino f) {
                var msg = f.abrirFecharCapota() ? "abrindo capota" : "fechando capota";
                IO.println(msg);
            }
            if (c instanceof FerrariPortoFino f) {
                var msg = f.ligarEstabilidade() ? "ligando estabilidade" : "desligando estabilidade";
                IO.println(msg);
            }

            // Chevrolet
            if (c instanceof ChevroletS10 f) {
                var msg = f.ativarDesativarTração() ? "ativando tração" : "desativando tração";
                IO.println(msg);
            }
            if (c instanceof ChevroletS10 f) {
                var msg = f.abrirFecharCacamba() ? "abrindo caçamba" : "fechando caçamba";
                IO.println(msg);
            }

            // WaterCarPhanter

            if (c instanceof WaterCarPanther f) {
                var msg = f.abrirFecharCapota() ? "abrindo capota" : "fechando capota";
                IO.println(msg);
            }
            if (c instanceof WaterCarPanther f) {
                var msg = f.ativarDesativarTração() ? "ativando tração" : "desativando tração";
                IO.println(msg);
            }
            if (c instanceof WaterCarPanther f) {
                f.regularTempGeladeira(10);
                var msg = "temperatura da geladeira regulada para 10 graus";
                IO.println(msg);
            }
            if (c instanceof WaterCarPanther f) {
                var msg = f.encherLastro() ? "enchendo lastro" : "esvaziando lastro";
                IO.println(msg);
            }
            if (c instanceof WaterCarPanther f) {
                var msg = f.recolherEstendeRodas() ? "recolhendo rodas" : "estendendo rodas";
                IO.println(msg);
            }


        });


    }
}

